import { useState } from 'react';

export default function {{component_name}}({ onFiles }: { onFiles?: (f: File[]) => void }) {
  const [over, setOver] = useState(false);

  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    setOver(false);
    const files = Array.from(e.dataTransfer.files);
    onFiles?.(files);
  }

  return (
    <div
      onDragOver={(e) => { e.preventDefault(); setOver(true); }}
      onDragLeave={() => setOver(false)}
      onDrop={onDrop}
      className={`border-2 border-dashed rounded p-8 text-center ${over ? 'bg-blue-50 border-blue-400' : 'border-gray-300'}`}
    >
      Drop files here
    </div>
  );
}
